selected.compute:
options = read('/input/options')
current = read('/output/selection')
if valid(current):
    result = current
else:
    result = []
    for group in combinations(options, goal['min_count']):
        ids = [item['id'] for item in group]
        if valid(ids):
            result = ids
            break

selected.effects:
if not exists('/output/selection'):
    write('/output/selection', result)
if status('report') == 'not_sent':
    send('report', 'team', read('/output/selection'))
if exists('/tmp/cache'):
    delete('/tmp/cache')
